CREATE TABLE IF NOT EXISTS users (email VARCHAR(191) PRIMARY KEY, name VARCHAR(191) NOT NULL, password_hash VARCHAR(255) NULL, role VARCHAR(32) NOT NULL, is_approved BOOLEAN NOT NULL DEFAULT FALSE, data JSON NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_users_role_approved (role,is_approved)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS harvests (id VARCHAR(64) PRIMARY KEY, farmer_email VARCHAR(191) NOT NULL, status VARCHAR(32) NOT NULL, harvest_date DATE NULL, moisture_level DECIMAL(5,2) NULL, data JSON NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_harvests_farmer (farmer_email), INDEX idx_harvests_status_date (status,harvest_date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS service_requests (id VARCHAR(64) PRIMARY KEY, harvest_id VARCHAR(64) NULL, farmer_email VARCHAR(191) NOT NULL, service_type VARCHAR(32) NOT NULL, status VARCHAR(32) NOT NULL, data JSON NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_services_farmer (farmer_email), INDEX idx_services_type_status (service_type,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS offered_services (id VARCHAR(64) PRIMARY KEY, provider_email VARCHAR(191) NOT NULL, service_type VARCHAR(32) NOT NULL, is_available BOOLEAN NOT NULL DEFAULT TRUE, data JSON NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_offered_provider (provider_email), INDEX idx_offered_available (service_type,is_available)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS offers (id VARCHAR(64) PRIMARY KEY, harvest_id VARCHAR(64) NOT NULL, buyer_email VARCHAR(191) NOT NULL, farmer_email VARCHAR(191) NOT NULL, status VARCHAR(32) NOT NULL, data JSON NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_offers_harvest (harvest_id), INDEX idx_offers_buyer (buyer_email), INDEX idx_offers_farmer_status (farmer_email,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS production_loans (id VARCHAR(64) PRIMARY KEY, farmer_email VARCHAR(191) NOT NULL, buyer_email VARCHAR(191) NOT NULL, status VARCHAR(32) NOT NULL, requested_amount DECIMAL(14,2) NOT NULL, data JSON NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_loans_farmer (farmer_email), INDEX idx_loans_buyer_status (buyer_email,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS notifications (id VARCHAR(64) PRIMARY KEY, user_email VARCHAR(191) NOT NULL, is_read BOOLEAN NOT NULL DEFAULT FALSE, notification_type VARCHAR(32) NOT NULL, data JSON NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_notifications_user_read (user_email,is_read)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS iot_devices (device_id VARCHAR(100) PRIMARY KEY, gateway_id VARCHAR(100), device_name VARCHAR(191), is_active BOOLEAN NOT NULL DEFAULT TRUE, last_seen_at DATETIME, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS moisture_readings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, harvest_id VARCHAR(64), batch_id VARCHAR(100) NOT NULL, farmer_email VARCHAR(191), farmer_name VARCHAR(191), raw_value DECIMAL(12,4) NULL, moisture_percentage DECIMAL(5,2) NOT NULL, quality_classification VARCHAR(100) NOT NULL, device_id VARCHAR(100) NOT NULL, gateway_id VARCHAR(100), recorded_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_moisture_harvest_time (harvest_id,recorded_at), INDEX idx_moisture_batch_time (batch_id,recorded_at), INDEX idx_moisture_device (device_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS system_settings (setting_key VARCHAR(100) PRIMARY KEY, setting_value JSON NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT IGNORE INTO system_settings (setting_key,setting_value) VALUES ('daReferencePrice','22.8');
CREATE TABLE IF NOT EXISTS email_deliveries (notification_id VARCHAR(64) PRIMARY KEY, recipient_email VARCHAR(191) NOT NULL, delivery_status VARCHAR(24) NOT NULL DEFAULT 'pending', attempts SMALLINT UNSIGNED NOT NULL DEFAULT 0, last_error VARCHAR(500) NULL, sent_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_email_delivery_recipient (recipient_email,delivery_status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ai_daily_usage (user_email VARCHAR(191) NOT NULL, usage_date DATE NOT NULL, questions_used INT UNSIGNED NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (user_email,usage_date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
